def transform5(grid):
    coords=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    r0,r1=min(r for r,c in coords),max(r for r,c in coords); c0,c1=min(c for r,c in coords),max(c for r,c in coords)
    out=[]
    for r in range(r0,r1+1):
        sr=31-r
        if grid[sr][c0]==8: out.append([4,4,7])
        else: out.append([grid[sr][c] for c in range(c0,c1+1)])
    return out
